/**
 * Every math instruction is read aloud: first graders cannot read the questions yet. One fixed
 * sentence per kind of question, generated by scripts/generate-math-audio.ts.
 */
const numerals = ["零", "一", "兩", "三", "四", "五", "六", "七", "八", "九", "十"];
const numeralReadings = "ㄌㄧㄥˊ ㄧ ㄌㄧㄤˇ ㄙㄢ ㄙˋ ㄨˇ ㄌㄧㄡˋ ㄑㄧ ㄅㄚ ㄐㄧㄡˇ ㄕˊ".split(" ");
/** In a sum, 2 is 二, not 兩: 二加三. */
const sumNumerals = ["零", "一", "二", ...numerals.slice(3)];
const sumReadings = ["ㄌㄧㄥˊ", "ㄧ", "ㄦˋ", ...numeralReadings.slice(3)];
export const chineseNumber = (value: number) => numerals[value] ?? String(value);

const range = (from: number, to: number) =>
  Array.from({ length: to - from + 1 }, (_, index) => from + index);
/** Every sum 第三課 can ask: 合在一起 has up to 5 on each side; 畫圈圈 sums are 3 to 10. */
const joinPairs = range(1, 5).flatMap((a) => range(1, 5).map((b) => [a, b] as const));
const addPairs = range(1, 9).flatMap((a) =>
  range(1, 9)
    .filter((b) => a + b >= 3 && a + b <= 10)
    .map((b) => [a, b] as const),
);

export const mathPrompts: Record<string, string> = {
  count: "數一數，有幾個？用筆寫出數字。",
  ...Object.fromEntries(
    numerals
      .slice(1)
      .map((_, index) => [`draw-${index + 1}`, `畫出${chineseNumber(index + 1)}個圈圈。`]),
  ),
  // 第二課 比一比
  "length-more": "哪一枝鉛筆比較長？點一下。",
  "length-less": "哪一枝鉛筆比較短？點一下。",
  "height-more": "哪一個小朋友比較高？點一下。",
  "height-less": "哪一個小朋友比較矮？點一下。",
  "align-length": "鉛筆沒有對齊。先把每一枝鉛筆拉到紅線。",
  "align-height": "有人站在箱子上。先把小朋友拉到地上。",
  "order-length": "先點最短的，再點中間的，最後點最長的。",
  "order-height": "先點最矮的，再點中間的，最後點最高的。",
  "line-straight": "哪一條是直線？點一下。",
  "line-curve": "哪一條是曲線？點一下。",
  route: "小兔子要去拿紅蘿蔔。哪一條路最近？點一下。",
  correct: "答對了！",
  retry: "再想想看。",
  // 第三課 加法
  ...Object.fromEntries(
    joinPairs.map(([a, b]) => [
      `join-${a}-${b}`,
      `左邊有${numerals[a]}個，右邊有${numerals[b]}個，合在一起有幾個？`,
    ]),
  ),
  ...Object.fromEntries(
    addPairs.map(([a, b]) => [
      `add-${a}-${b}`,
      `${sumNumerals[a]}加${sumNumerals[b]}等於多少？先畫圈圈，再寫答案。`,
    ]),
  ),
};

